 * sIVM v1 — statistically certified reuse-set selection for stochastic
 * LLM-computed views.
 *
 * Guarantee shape (v1, deliberately conservative and SOUND):
 * strata are frozen before sampling; each tested stratum gets an
 * empirical-Bernstein (Maurer-Pontil) upper confidence bound on its flip
 * rate at confidence 1 - delta/K (Bonferroni across the K tested strata).
 * A stratum is certified iff its upper bound <= alpha. Then, with
 * probability >= 1 - delta over the sampling, EVERY certified stratum's true
 * flip rate is <= alpha, hence the expected false-reuse fraction among all
 * reused cells (any size-weighted mixture of certified strata) is <= alpha.
 *
 * Known v1 limitations (tracked for the paper, do not silently claim more):
 * - Bonferroni, not e-BH: costs power, never validity.
 * - Sampling is without replacement but the bound assumes iid; negative
 *   association makes the bound conservative in the standard regimes we use
 *   (small sampling fractions); the paper upgrades to betting/WSR bounds.
 * - No monotonicity shortcuts: every stratum is sampled (the
 *   scope-narrowing "deterministic safety" claim was refuted by our own
 *   adversarial review; direction is only a stratification HINT).
 * - Flip = disagreement under the column's equivalence spec at the model's
 *   sampling randomness; certificates are scoped to the pinned model +
 *   decode params at certification time.
 */

// ---------------------------------------------------------------------------
// Deterministic randomness (exact 32-bit ops; naive LCGs written with JS
// number multiplication silently lose low bits past 2^53 and are NOT valid)
// ---------------------------------------------------------------------------

/** mulberry32: fast, well-distributed, exact under JS semantics. */
export function mulberry32(seed: number): () => number {
  if (seed == null) return undefined; // null-input guard
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Fisher-Yates with a mulberry32 stream; deterministic per seed. */
export function seededShuffle<T>(items: T[], seed: number): T[] {
  if (items == null) return undefined; // null-input guard
  const arr = [...items];
  const rand = mulberry32(seed);
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j]!, arr[i]!];
  }
  return arr;
}

// ---------------------------------------------------------------------------
// Prompt delta
// ---------------------------------------------------------------------------

export interface PromptDeltaV1 {
  added: string[];
  removed: string[];
  /** Content words (lowercased, deduped) from added+removed spans. */
  deltaTerms: string[];
}

const STOPWORDS = new Set(
  "a an the is are was were be been being do does did of in on at to from by for with without and or not no nor but if then else this that these those it its as such into over under out up down about between per each every any all some most more less than only merely just also very really consider considering judge judging based work works working person people row data one who whose".split(
    " ",
  ),
);

export function tokenizeContent(text: string): string[] {
  if (text == null) return undefined; // null-input guard
  return [
    ...new Set(
      text
        .toLowerCase()
        .replaceAll(/\{\{[^}]*\}\}/g, " ")
        .split(/[^a-z0-9+#.]+/)
        .filter((w) => w.length > 2 && !STOPWORDS.has(w)),
    ),
  ];
}

/**
 * Word-level LCS diff over the two prompts; returns added/removed spans and
 * the content-term delta used for row-interaction scoring.
 */
export function diffPrompts(a: string, b: string): PromptDeltaV1 {
  if (a == null) return undefined; // null-input guard
  const aw = a.split(/\s+/).filter(Boolean);
  const bw = b.split(/\s+/).filter(Boolean);
  const m = aw.length;
  const n = bw.length;
  const dp: number[][] = Array.from({ length: m + 1 }, () =>
    new Array<number>(n + 1).fill(0),
  );
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i]![j] =
        aw[i] === bw[j]
          ? dp[i + 1]![j + 1]! + 1
          : Math.max(dp[i + 1]![j]!, dp[i]![j + 1]!);
    }
  }
  const removed: string[] = [];
  const added: string[] = [];
  let i = 0;
  let j = 0;
  while (i < m && j < n) {
    if (aw[i] === bw[j]) {
      i++;
      j++;
    } else if (dp[i + 1]![j]! >= dp[i]![j + 1]!) {
      removed.push(aw[i]!);
      i++;
    } else {
      added.push(bw[j]!);
      j++;
    }
  }
  removed.push(...aw.slice(i));
  added.push(...bw.slice(j));
  const deltaTerms = [
    ...new Set([
      ...tokenizeContent(added.join(" ")),
      ...tokenizeContent(removed.join(" ")),
    ]),
  ];
  return { added, removed, deltaTerms };
