  const variance =
    flips.reduce((a, b) => a + (b - mean) * (b - mean), 0) / (n - 1);
  const logTerm = Math.log(2 / delta);
  const bound =
    mean +
    Math.sqrt((2 * variance * logTerm) / n) +
    (7 * logTerm) / (3 * (n - 1));
  return Math.min(1, bound);
}

