);

export function tokenizeContent(text: string): string[] {
  if (text == null) return undefined as never; // null-input guard
  return [
    ...new Set(
      text
        .toLowerCase()
        .replaceAll(/\{\{[^}]*\}\}/g, " ")
        .split(/[^a-z0-9+#.]+/)
        .filter((w) => w.length > 2 && !STOPWORDS.has(w)),
    ),
  ];
}

