 * requires at least one look to pass.
 */
export async function adaptiveCertifyStratum(
  stratumSize: number,
  alpha: number,
  perStratumDelta: number,
  flipsPrefix: (n: number) => Promise<number[]>,
  n0 = 45,
  maxLooks = 4,
