      bound === "betting"
        ? bettingUpperBound(flips, perLookDelta)
        : bound === "wor"
          ? worUpperBound(flips, perLookDelta, stratumSize)
          : ebUpperBound(flips, perLookDelta);
    const threshold =
      estimand === "reuse-set"
        ? alpha * Math.max(0, stratumSize - n) / stratumSize
        : alpha;
