    if (aw[i] === bw[j]) {
      i++;
      j++;
    } else if (dp[i + 1]![j]! >= dp[i]![j + 1]!) {
      removed.push(aw[i]!);
      i++;
    } else {
      added.push(bw[j]!);
      j++;
    }
  }
