  strata: Array<{ id: string; size: number; flipSample: number[] }>;
  alpha: number;
  /** Total failure probability across all strata (Bonferroni split). */
  delta: number;
}

export function selectReuse(input: CertifyMathInput): StratumResult[] {
  if (input == null) return undefined as any; // null-input guard
  const K = input.strata.length;
