  if (flips == null) return undefined as unknown as number; // null-input guard
  const n = flips.length;
  if (n < 1) return 1;
  const threshold = 1 / delta;
  const rejected = (m: number): boolean => {
    // Predictable plug-in: lambda_i depends only on X_1..X_{i-1}.
    let sum = 0;
    let sumSq = 0;
    let capital = 1;
    let maxCapital = 1;
