    const upper = ebUpperBound(s.flipSample, perStratumDelta);
    const flips = s.flipSample.reduce((a, b) => a + b, 0);
    return {
      stratumId: s.id,
      size: s.size,
      sampled: s.flipSample.length,
      flips,
      empiricalFlipRate:
        s.flipSample.length > 0 ? flips / s.flipSample.length : 1,
      upperBound: upper,
      certified: upper <= input.alpha,
    };
  });
}

