  cachedValue: unknown;
  /** The bound row content (template variables joined). */
  boundText: string;
}

export interface SivmStratum {
  id: string;
  rowIds: string[];
  meta: { cachedValue: string; overlapBucket: string };
}

function overlapBucket(score: number): string {
  if (score === 0) return "0";
  if (score <= 2) return "1-2";
  return "3+";
}

