      text
        .toLowerCase()
        .replaceAll(/\{\{[^}]*\}\}/g, " ")
        .split(/[^a-z0-9+#.]+/)
        .filter((w) => w.length > 2 && !STOPWORDS.has(w)),
    ),
  ];
